'use strict';

/**
 * Load the prebuilt native binding — and fail loudly if there is none.
 *
 * The actual loading is done by the napi-rs generated loader in
 * `./binding.js` (regenerated by `npm run build`; do not hand-edit it).
 * It tries a locally built `./bun-rusty-opus.<triple>.node` first, then the
 * platform package `@ndqp/bun-rusty-opus-<triple>` installed as an
 * optionalDependency. This file only translates its failure into the
 * package's own error, so users get a clear message instead of napi-rs's
 * generic "Cannot find native binding".
 *
 * There is intentionally NO build fallback here: no cargo, no node-gyp,
 * no postinstall compile. If no prebuilt fits this machine, `require()`
 * throws (and the `postinstall` check in `scripts/check-prebuilt.js`
 * makes `npm install` / `bun install` fail at install time instead of
 * at first use).
 */

const fs = require('node:fs');
const path = require('node:path');

const BINARY_NAME = 'bun-rusty-opus';

/** All triples CI builds (see .github/workflows/release.yml). */
const SUPPORTED_TARGETS = [
  'darwin-x64',
  'darwin-arm64',
  'linux-x64-gnu',
  'linux-x64-musl',
  'linux-arm64-gnu',
  'linux-arm64-musl',
  'win32-x64-msvc',
  'win32-arm64-msvc',
];

function isMusl() {
  try {
    if (fs.existsSync('/etc/alpine-release')) return true;
    const { execFileSync } = require('node:child_process');
    const out = execFileSync('ldd', ['--version'], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
    return /musl/i.test(out);
  } catch {
    return false;
  }
}

function candidateTriples() {
  const platform = process.platform;
  const arch = process.arch;
  if (platform === 'linux') {
    const libc = isMusl() ? 'musl' : 'gnu';
    const other = libc === 'musl' ? 'gnu' : 'musl';
    return [`linux-${arch}-${libc}`, `linux-${arch}-${other}`];
  }
  if (platform === 'darwin') return [`darwin-${arch}`];
  if (platform === 'win32') return [`win32-${arch}-msvc`];
  return [];
}

function loadNative() {
  const bindingPath = path.join(__dirname, '..', 'binding.js');
  if (!fs.existsSync(bindingPath)) {
    // Fresh checkout before any build — a dev problem, not a prebuilt one.
    throw new Error(
      '@ndqp/bun-rusty-opus: native binding has not been built yet (binding.js is missing). ' +
        'Build it with `npm run build` (or `npm run build:local` for a native-CPU build).',
    );
  }
  try {
    return require(bindingPath);
  } catch (err) {
    const detected = `${process.platform}-${process.arch}${process.platform === 'linux' ? (isMusl() ? '-musl' : '-gnu') : ''}`;
    const error = new Error(
      `@ndqp/bun-rusty-opus: no prebuilt native binary for this machine (${detected}).\n` +
        `Supported targets: ${SUPPORTED_TARGETS.join(', ')}.\n` +
        `This package ships prebuilt binaries only and does not build from source on install. ` +
        `If your platform is not listed, please open an issue at ` +
        `https://github.com/nemesisqp/bun-rusty-opus/issues — do not try to build it by hand on this machine.\n` +
        `Underlying loader error: ${err.message}`,
    );
    error.code = 'ERR_BUN_RUSTY_OPUS_NO_PREBUILT';
    error.cause = err;
    throw error;
  }
}

module.exports = { loadNative, candidateTriples, SUPPORTED_TARGETS, BINARY_NAME };
